    // ── Scalar (reference) path ─────────────────────────────────────────────

    private void IteratePixelScalar(double cr, double ci, uint[] buf, int idx)
    {
        double zr = 0.0, zi = 0.0;
        double dr = 0.0, di = 0.0;
        int it = 0;
        int maxIt = MaxIterations;
        for (; it < maxIt; it++)
        {
            double r2 = zr * zr + zi * zi;
            if (r2 >= Bailout2) break;
            double dr_new = (((zr + zr) * dr - (zi + zi) * di) + 1.0);
            double di_new = ((zr + zr) * di + (zi + zi) * dr);
            double zr_new = ((zr * zr - zi * zi) + cr);
            double zi_new = ((zr * zi + zi * zr) + ci);
            zr = zr_new; zi = zi_new;
            dr = dr_new; di = di_new;
        }
        buf[idx] = ColorFor(it, zr, zi, dr, di, maxIt);
    }

    // Iteration-count-only variant (no colour writeback). Used by the
