            if (r2 >= Bailout2) break;
            double dr_new = (((zr + zr) * dr - (zi + zi) * di) + 1.0);
            double di_new = ((zr + zr) * di + (zi + zi) * dr);
            double zr_new = ((zr * zr - zi * zi) + cr);
            double zi_new = ((zr * zi + zi * zr) + ci);
            zr = zr_new; zi = zi_new;
            dr = dr_new; di = di_new;
