    }

    // ── AVX2 path (4 pixels per lane) ───────────────────────────────────────

    private void IterateLaneAvx2(Vector256<double> cr, Vector256<double> ci, uint[] buf, int idx)
    {
        Vector256<double> zr = Vector256<double>.Zero;
        Vector256<double> zi = Vector256<double>.Zero;
        Vector256<double> dr = Vector256<double>.Zero;
        Vector256<double> di = Vector256<double>.Zero;
        Vector256<double> bailoutVec = Vector256.Create(Bailout2);
        Vector256<long> itCounts = Vector256<long>.Zero;
        Vector256<long> oneL = Vector256.Create(1L);
        Vector256<long> activeLanes = Vector256.Create(-1L);   // all lanes active initially

        int maxIt = MaxIterations;
        for (int n = 0; n < maxIt; n++)
        {
            var r2 = Fma.MultiplyAdd(zr, zr, Avx.Multiply(zi, zi));
            // active = (r2 < bailout) — lanes that have NOT yet escaped
            var activeMaskD = Avx.Compare(r2, bailoutVec, FloatComparisonMode.OrderedLessThanNonSignaling);
            var activeMaskL = activeMaskD.AsInt64();
            activeLanes = Avx2.And(activeLanes, activeMaskL);
            if (Avx.MoveMask(activeMaskD) == 0) break;
            itCounts = Avx2.Add(itCounts, Avx2.And(oneL, activeMaskL));

                Vector256<double> d_re1 = Avx.Add(zr, zr);
                Vector256<double> d_im2 = Avx.Add(zi, zi);
                Vector256<double> d_re3 = Fma.MultiplyAddNegated(d_im2, di, Avx.Multiply(d_re1, dr));
                Vector256<double> d_im4 = Fma.MultiplyAdd(d_re1, di, Avx.Multiply(d_im2, dr));
                Vector256<double> d_re5 = Vector256.Create(1.0);
                Vector256<double> d_re6 = Avx.Add(d_re3, d_re5);
                Vector256<double> dr_new = d_re6;
                Vector256<double> di_new = d_im4;
                Vector256<double> z_re1 = Fma.MultiplyAddNegated(zi, zi, Avx.Multiply(zr, zr));
                Vector256<double> z_im2 = Fma.MultiplyAdd(zr, zi, Avx.Multiply(zi, zr));
                Vector256<double> z_re3 = Avx.Add(z_re1, cr);
                Vector256<double> z_im4 = Avx.Add(z_im2, ci);
                Vector256<double> zr_new = z_re3;
                Vector256<double> zi_new = z_im4;

            // Freeze z, dz/dc for any lane that escaped this iteration; live
            // lanes pick up the new values.
            var keepD = activeMaskL.AsDouble();
            zr = Avx.BlendVariable(zr, zr_new, keepD);
            zi = Avx.BlendVariable(zi, zi_new, keepD);
            dr = Avx.BlendVariable(dr, dr_new, keepD);
            di = Avx.BlendVariable(di, di_new, keepD);
        }

        Span<long> its = stackalloc long[4];
        Span<double> zrs = stackalloc double[4];
        Span<double> zis = stackalloc double[4];
        Span<double> drs = stackalloc double[4];
        Span<double> dis = stackalloc double[4];
        itCounts.CopyTo(its);
        zr.CopyTo(zrs); zi.CopyTo(zis);
        dr.CopyTo(drs); di.CopyTo(dis);
        for (int k = 0; k < 4; k++)
            buf[idx + k] = ColorFor((int)its[k], zrs[k], zis[k], drs[k], dis[k], MaxIterations);
    }

    // Iteration-count-only variant for the self-test (no colour writeback).
    internal void IterateLaneAvx2Raw(Vector256<double> cr, Vector256<double> ci,
                                      Span<int> outIters)
    {
        Vector256<double> zr = Vector256<double>.Zero;
        Vector256<double> zi = Vector256<double>.Zero;
        Vector256<double> dr = Vector256<double>.Zero;
        Vector256<double> di = Vector256<double>.Zero;
        Vector256<double> bailoutVec = Vector256.Create(Bailout2);
        Vector256<long> itCounts = Vector256<long>.Zero;
        Vector256<long> oneL = Vector256.Create(1L);

        int maxIt = MaxIterations;
        for (int n = 0; n < maxIt; n++)
        {
            var r2 = Fma.MultiplyAdd(zr, zr, Avx.Multiply(zi, zi));
            var activeMaskD = Avx.Compare(r2, bailoutVec, FloatComparisonMode.OrderedLessThanNonSignaling);
            var activeMaskL = activeMaskD.AsInt64();
            if (Avx.MoveMask(activeMaskD) == 0) break;
            itCounts = Avx2.Add(itCounts, Avx2.And(oneL, activeMaskL));

                Vector256<double> d_re1 = Avx.Add(zr, zr);
                Vector256<double> d_im2 = Avx.Add(zi, zi);
                Vector256<double> d_re3 = Fma.MultiplyAddNegated(d_im2, di, Avx.Multiply(d_re1, dr));
                Vector256<double> d_im4 = Fma.MultiplyAdd(d_re1, di, Avx.Multiply(d_im2, dr));
                Vector256<double> d_re5 = Vector256.Create(1.0);
                Vector256<double> d_re6 = Avx.Add(d_re3, d_re5);
                Vector256<double> dr_new = d_re6;
                Vector256<double> di_new = d_im4;
                Vector256<double> z_re1 = Fma.MultiplyAddNegated(zi, zi, Avx.Multiply(zr, zr));
                Vector256<double> z_im2 = Fma.MultiplyAdd(zr, zi, Avx.Multiply(zi, zr));
                Vector256<double> z_re3 = Avx.Add(z_re1, cr);
                Vector256<double> z_im4 = Avx.Add(z_im2, ci);
                Vector256<double> zr_new = z_re3;
                Vector256<double> zi_new = z_im4;

            var keepD = activeMaskL.AsDouble();
            zr = Avx.BlendVariable(zr, zr_new, keepD);
            zi = Avx.BlendVariable(zi, zi_new, keepD);
            dr = Avx.BlendVariable(dr, dr_new, keepD);
            di = Avx.BlendVariable(di, di_new, keepD);
        }

        Span<long> its = stackalloc long[4];
        itCounts.CopyTo(its);
        for (int k = 0; k < 4; k++) outIters[k] = (int)its[k];
    }

    // ── Colour mapping ──────────────────────────────────────────────────────
    //
    // Uses the nine-parameter IColorMap.Map overload so themes get smooth
    // count, distance estimate, normal direction, final z, and final dz/dc.
    // Themes that ignore these inherit the default 3-arg fallback via the
    // interface's default implementations.

    private uint ColorFor(int it, double zr, double zi, double dr, double di, int maxIt)
    {
        if (it >= maxIt) return ColorMap.InSetColor;

        double zMag2 = zr * zr + zi * zi;
        double zMag  = Math.Sqrt(zMag2);
        double dMag2 = dr * dr + di * di;
        double dMag  = Math.Sqrt(dMag2);

        // Smooth iteration count: standard log-log normalisation.
        float smooth = (float)(it + 1.0
            - Math.Log2(Math.Max(1e-10, Math.Log2(Math.Max(zMag, 1.0 + 1e-10)))));

        // Surface normal (Inigo Quilez): u + v·i  ∝  z · conj(dz/dc)
        //   u = zr·dr + zi·di
        //   v = zi·dr − zr·di
        double u = zr * dr + zi * di;
        double v = zi * dr - zr * di;
        double m = Math.Sqrt(u * u + v * v);
        float nx = 0f, ny = 0f;
        if (m > 1e-30) { nx = (float)(u / m); ny = (float)(v / m); }

        // Exterior distance estimate (Milnor / Hubbard):
        //   d ≈ 0.5 · |z| · log|z| / |dz/dc|
        // Returned in complex-plane units; themes scale by _lastPixelScale.
        float distance = 0f;
        if (dMag > 1e-30 && zMag > 1.0)
            distance = (float)(0.5 * zMag * Math.Log(zMag) / dMag);

        return (uint)ColorMap.Map(
            smooth, distance, maxIt, nx, ny,
            (float)zr, (float)zi, (float)dr, (float)di);
    }
